#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
uniform float2 amzVelocity,amzPivot,amzScale;
uniform float amzAngularVelocity,amzScaleVelocity,amzStartTime,amzEndTime;

struct AC_ImageInfo { int texture; float2 amzLocal_size; };
const float3x3 labPlaneInverse=float3x3(1);
float4x4 amzQuaternion(float4 q) {
    q /= max(length(q),0.000001);
    float x=q.x,y=q.y,z=q.z,w=q.w;
    return float4x4(1-2*(y*y+z*z),2*(x*y+w*z),2*(x*z-w*y),0,
                    2*(x*y-w*z),1-2*(x*x+z*z),2*(y*z+w*x),0,
                    2*(x*z+w*y),2*(y*z-w*x),1-2*(x*x+y*y),0,0,0,0,1);
}
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval(((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0))); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
float4 amzTexture(int tex,float2 uv,float bias){return amzTexture(tex,uv);}
uniform float amzp_style;
uniform float amzp_gridPattern;
uniform float amzp_gridStrength;
uniform float amzp_gridColor;
uniform float amzp_gridScale;
uniform float amzp_scanlines;
uniform float amzp_rgbSplit;
uniform float amzp_ghost;
uniform float amzp_ghostX;
uniform float amzp_ghostY;
uniform float amzp_colorBar;
uniform float amzp_barPosition;
uniform float amzp_barHeight;
uniform float amzp_exposureFix;
uniform float amzp_noiseLevel;
uniform float amzp_vibrance;
uniform float amzp_sharpness;
uniform float amzp_glow;
uniform float amzp_colorize;
uniform float amzp_glitches;
uniform float amzp_glitchAmount;
uniform float amzp_tvBorders;
uniform float amzp_borderCurve;
uniform float amzp_intensity;
    float rnd(float2 co){
        float dt = dot(co, float2(12.9898, 78.233));
        return fract(sin(mod(dt, 3.14159265)) * 43758.5453);
    }
    float luma(float3 c){ return dot(c, float3(0.299, 0.587, 0.114)); }
    float3 hsv2rgb(float3 c){
        float4 K = float4(1.0, 2.0/3.0, 1.0/3.0, 3.0);
        float3 p = abs(fract(c.xxx + K.xyz) * 6.0 - K.www);
        return c.z * mix(K.xxx, clamp(p - K.xxx, 0.0, 1.0), c.y);
    }
    float2 barrelWarp(float2 uv, float2 center, float aspect, float k){
        float2 d = uv - center;
        d.x *= aspect;
        d *= 1.0 + k * dot(d, d) * 2.0;
        d.x /= aspect;
        return center + d;
    }
    void amzRender(){
        float2 center = (amzLayerCenter()/screen.zw);
        float aspect = screen.zw.x / screen.zw.y;
        float3 tint = float3(1.0);
        float3 glowTint = float3(1.0);
        float con = 1.06;
        float satB = 0.0;
        float brightB = 0.0;
        float styleAber = 0.006;
        float styleGlow = 0.12;
        if(int(amzp_style) == 1){ tint=float3(1.0,1.0,1.0); con=1.05; satB=0.0; glowTint=float3(1.0); styleAber=0.005; styleGlow=0.10; }
        else if(int(amzp_style) == 2){ tint=float3(1.08,1.0,0.90); con=1.06; satB=0.06; glowTint=float3(1.1,0.95,0.8); styleAber=0.008; styleGlow=0.14; }
        else if(int(amzp_style) == 3){ tint=float3(1.0,1.0,1.0); con=1.22; satB=-0.30; glowTint=float3(1.0); styleAber=0.004; styleGlow=0.10; }
        else if(int(amzp_style) == 4){ tint=float3(0.90,1.00,1.05); con=1.10; satB=0.10; glowTint=float3(0.6,0.9,1.0); styleAber=0.0025; styleGlow=0.30; }
        else if(int(amzp_style) == 5){ tint=float3(1.0,1.0,1.0); con=1.06; satB=0.0; glowTint=float3(1.0); styleAber=0.006; styleGlow=0.10; }
        else if(int(amzp_style) == 6){ tint=float3(0.70,1.18,0.80); con=1.12; satB=0.12; glowTint=float3(0.3,1.1,0.4); styleAber=0.006; styleGlow=0.35; }
        else if(int(amzp_style) == 7){ tint=float3(1.12,0.85,1.10); con=1.10; satB=0.12; glowTint=float3(1.1,0.4,1.0); styleAber=0.009; styleGlow=0.38; }
        else if(int(amzp_style) == 8){ tint=float3(1.14,0.98,0.72); con=1.04; satB=-0.18; glowTint=float3(1.1,0.9,0.6); styleAber=0.006; styleGlow=0.16; }
        else if(int(amzp_style) == 9){ tint=float3(1.0,1.0,1.0); con=1.34; satB=0.05; glowTint=float3(1.0); styleAber=0.006; styleGlow=0.12; }
        else if(int(amzp_style) == 10){ tint=float3(0.72,1.02,1.06); con=1.12; satB=0.10; glowTint=float3(0.4,1.05,1.05); styleAber=0.009; styleGlow=0.40; }
        else if(int(amzp_style) == 11){ tint=float3(0.95,0.85,1.18); con=1.12; satB=0.10; glowTint=float3(0.7,0.4,1.2); styleAber=0.010; styleGlow=0.40; }
        else if(int(amzp_style) == 12){ tint=float3(0.92,0.96,1.06); con=1.18; satB=0.12; brightB=0.05; glowTint=float3(1.0,0.6,1.0); styleAber=0.012; styleGlow=0.50; }
        float ga = amzp_glitchAmount / 100.0;
        float2 suv = amzScreenNorm();
        if(int(amzp_glitches) == 2){
            suv.x += ga * 0.03 * sin(amzScreenNorm().y * 130.0 + time * 9.0);
        } else if(int(amzp_glitches) == 3){
            suv.y = fract(suv.y - (0.15 + ga * 0.8) * time);
        } else if(int(amzp_glitches) == 4){
            float2 bc = floor(amzScreenNorm() * float2(18.0, 14.0));
            float r = rnd(bc + floor(time * 12.0));
            if(r > 1.0 - ga * 0.6){ suv.x += (rnd(bc + 1.7) - 0.5) * ga * 0.12; }
        }
        if((amzp_tvBorders>0.5)){
            suv = barrelWarp(suv, center, aspect, amzp_borderCurve);
        }
        float aber = styleAber * amzp_rgbSplit + (int(amzp_glitches) == 1 ? ga * 0.025 : 0.0);
        float2 ro = float2(aber, 0.0);
        float4 orig = amzTexture(0, amzScreenNorm());
        float cr_ = amzTexture(0, suv + ro).r;
        float4 cg = amzTexture(0, suv);
        float cb_ = amzTexture(0, suv - ro).b;
        float4 col = float4(cr_, cg.g, cb_, cg.a);
        if(amzp_ghost > 0.001){
            float2 goff = float2(amzp_ghostX, amzp_ghostY) / layer;
            float3 gh1 = amzTexture(0, suv + goff).rgb;
            float3 gh2 = amzTexture(0, suv - goff).rgb;
            col.rgb = max(col.rgb, max(gh1, gh2) * amzp_ghost);
        }
        if(amzp_sharpness > 0.5){
            float sp = 0.0016;
            float3 bl = amzTexture(0, suv + float2(sp,0.0)).rgb
                    + amzTexture(0, suv - float2(sp,0.0)).rgb
                    + amzTexture(0, suv + float2(0.0,sp)).rgb
                    + amzTexture(0, suv - float2(0.0,sp)).rgb;
            bl *= 0.25;
            col.rgb += (col.rgb - bl) * (amzp_sharpness / 100.0) * 2.0;
        }
        float amzSource_gl = amzp_glow / 100.0 + styleGlow;
        if(amzSource_gl > 0.001){
            float d = 0.006 + amzSource_gl * 0.012;
            float3 b = amzTexture(0, suv + float2(d,0.0)).rgb
                   + amzTexture(0, suv - float2(d,0.0)).rgb
                   + amzTexture(0, suv + float2(0.0,d)).rgb
                   + amzTexture(0, suv - float2(0.0,d)).rgb
                   + amzTexture(0, suv + float2(d,d)*0.7).rgb
                   + amzTexture(0, suv + float2(-d,d)*0.7).rgb;
            b *= (1.0/6.0);
            col.rgb += max(b - 0.50, 0.0) * glowTint * amzSource_gl * 1.6;
        }
        if(amzp_gridStrength > 0.001){
            float gridAmt = mix(0.65, 1.0, smoothstep(0.0, 0.12, luma(col.rgb)));
            float cell = max(3.0, (layer.x / 150.0) / amzp_gridScale);
            float sub = cell / 3.0;
            float xpx = amzLayerNorm().x * layer.x;
            float ypx = amzLayerNorm().y * layer.y;
            float colIdx = floor(mod(xpx / sub, 3.0));
            float3 rgbmask = (colIdx < 0.5) ? float3(1.0,0.0,0.0)
                         : (colIdx < 1.5) ? float3(0.0,1.0,0.0)
                                          : float3(0.0,0.0,1.0);
            rgbmask = mix(float3(1.0), rgbmask * 3.0, amzp_gridColor);
            float prof;
            if(int(amzp_gridPattern) == 0){
                float dx = fract(xpx / sub) - 0.5;
                float dy = fract(ypx / cell) - 0.5;
                prof = 1.0 - smoothstep(0.30, 0.62, length(float2(dx, dy)));
                prof = 0.45 + 0.55 * prof;
            } else {
                prof = 0.5 + 0.5 * cos(6.28318530718 * (fract(xpx / sub) - 0.5));
                prof = 0.5 + 0.5 * prof;
            }
            prof /= 0.75;
            col.rgb = mix(col.rgb, col.rgb * rgbmask * prof, amzp_gridStrength * gridAmt);
        }
        if(amzp_scanlines > 0.001){
            float sgate = smoothstep(0.05, 0.40, luma(col.rgb));
            float spitch = max(2.0, (layer.y / 220.0) * amzp_gridScale);
            float ypx2 = amzLayerNorm().y * layer.y;
            float sline = 0.5 + 0.5 * cos(6.28318530718 * ypx2 / spitch);
            col.rgb *= 1.0 - amzp_scanlines * 0.6 * sgate * (1.0 - sline);
            col.rgb *= 1.0 + amzp_scanlines * 0.22 * sgate;
        }
        col.rgb *= tint;
        col.rgb = (col.rgb - 0.5) * con + 0.5 + brightB;
        col.rgb *= pow(2.0, amzp_exposureFix / 100.0);
        {
            float y = luma(col.rgb);
            float mx = max(max(col.r,col.g),col.b);
            float mn = min(min(col.r,col.g),col.b);
            float curSat = mx - mn;
            float v = amzp_vibrance / 100.0;
            float amt = v * (1.0 - curSat * 0.7) + satB;
            col.rgb = clamp(mix(float3(y), col.rgb, 1.0 + amt), 0.0, 1.0);
        }
        if(int(amzp_style) == 10){
            float a = amzp_colorize / 360.0 * 6.28318530718;
            float3 k = float3(0.57735);
            float cs = cos(a);
            col.rgb = col.rgb * cs + cross(k, col.rgb) * sin(a) + k * dot(k, col.rgb) * (1.0 - cs);
            col.rgb = clamp(col.rgb, 0.0, 1.0);
        }
        if(amzp_noiseLevel > 0.5){
            float darkGate = 1.0 - smoothstep(0.02, 0.35, luma(col.rgb));
            float ns = (amzp_noiseLevel / 10.0) * 0.35 * darkGate;
            float2 np = floor(amzLayerNorm() * layer / 2.0);
            float n = rnd(np + float2(floor(time * 24.0)));
            col.rgb = mix(col.rgb, float3(n) * col.a, ns);
        }
        if((amzp_colorBar>0.5) && amzp_barHeight > 0.001){
            float yN = amzLayerNorm().y;
            float inBar = (int(amzp_barPosition) == 0) ? step(yN, amzp_barHeight) : step(1.0 - amzp_barHeight, yN);
            if(inBar > 0.5){
                float hue = max(0.0, 0.667 * (1.0 - amzLayerNorm().x / 0.75));
                col.rgb = hsv2rgb(float3(hue, 1.0, 1.0));
            }
        }
        if((amzp_tvBorders>0.5)){
            float2 dluv = barrelWarp(amzLayerNorm(), float2(0.5), aspect, amzp_borderCurve);
            float2 q = abs(dluv - 0.5) * 2.0;
            float crad = 0.08;
            float2 dd = max(q - float2(1.0 - crad), 0.0);
            dd.x *= aspect;
            float edgeMask = 1.0 - smoothstep(crad, crad + 0.02, length(dd));
            float inside = step(0.0, dluv.x) * step(dluv.x, 1.0) * step(0.0, dluv.y) * step(dluv.y, 1.0);
            col *= edgeMask * inside;
            float2 vq = (dluv - 0.5) * 2.0;
            col.rgb *= 1.0 - 0.35 * smoothstep(0.4, 1.7, dot(vq, vq));
        }
        col.rgb = clamp(col.rgb, 0.0, 1.0);
        amzOutput = mix(orig, col, amzp_intensity);
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }

